Lemma cols_ok_col ns a nd : cols_ok [] ns -> ns !! a = Some nd -> 0 <= n_col nd < 2 /\ lw32 (n_col nd) = n_col nd.
Proof.
  intros CO L. pose proof (CO a nd L ltac:(rewrite elem_of_nil; intros F; exact F)) as K. unfold col_ok, RED, BLACK in K.
  unfold lw32. destruct (Z.ltb_spec (n_col nd) (2^31)); lia.
Qed.

(* [comment removed for export] *)
Ltac nal NSRk XAL H x :=
  lazymatch type of NSRk with NSR _ ?ns _ _ _ =>
    let nd := fresh "nd" in let L := fresh "L" in let A := fresh "AL" in let B := fresh "B" in
    let WF := fresh "WF" in let IN := fresh "IN" in let OUT := fresh "OUT" in let pad := fresh "pad" in let CH := fresh "CH" in
    mnode ns x nd L H;
    pose proof (NSR_al _ _ _ _ _ _ _ NSRk XAL L) as A; destruct A;
    destruct (NSR_node _ _ _ _ _ _ _ NSRk L) as (WF & IN & OUT & [pad CH]);
    pose proof (rw_cells_bound _ _ _ _ CH) as B; rewrite NodeCells_size in B;
    clear WF OUT CH pad L; clear nd
  end.

(* [comment removed for export] *)
Ltac nopen NSRk XAL H x CH :=
  lazymatch type of NSRk with NSR _ ?ns _ _ _ =>
    let nd := fresh "nd" in let L := fresh "L" in let A := fresh "AL" in
    mnode ns x nd L H; pose proof (NSR_al _ _ _ _ _ _ _ NSRk XAL L) as A; destruct A;
    mstep H L; nnode NSRk L CH; clear L
  end.
(* [comment removed for export] *)
Ltac name_fld prl :=
  match goal with
  | |- context [Z_to_bv 64 (n_lft ?nd)] => name_val (n_lft nd) prl
  | |- context [Z_to_bv 64 (n_rgt ?nd)] => name_val (n_rgt nd) prl
  | |- context [Z_to_bv 64 (n_par ?nd)] => name_val (n_par nd) prl
  end.

(* [comment removed for export] *)
Ltac cnstore NSRk CO H x k n mk :=
  lazymatch type of NSRk with NSR _ ?ns _ _ _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in let ML := fresh "ML" in let WL := fresh "WL" in
    let CO' := fresh "CO" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; pre_store CH k n ML WL; st1;
    let nd' := eval cbv beta in (mk nd) in
    pose proof (cols_ok_set _ _ _ _ nd' CO L ltac:(first [left; reflexivity | right; unfold col_ok, RED, BLACK; cbn; lia])) as CO';
    clear CO; rename CO' into CO;
    post_store NSRk L ML WL CH nd' k n; gen_store NSRk; clear L
  end.

