(* [comment removed for export] *)
Definition rotl_stmt : Prop := forall (gpv q gpp h : Z) (ns ns' : NS) (lo hi : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  NSR m ns lo hi X -> nodes_al X -> 0 <= h < 2^64 -> 0 <= gpv < 2^64 -> 0 <= q < 2^64 -> 0 <= gpp < 2^64 ->
  ub_rotate_left ns h gpv q gpp = Some ns' ->
  stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo + ROT_STACK <= bv_unsigned sp -> bv_unsigned sp <= hi ->
  mem_inv usegs m ->
  evt usegs (rebal_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns' lo hi X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz gpv) (wz q) (wz gpp) (wz h) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_ROTL) fc None m (seg_rom usegs)).

Local Ltac close_frame48 :=
  lazymatch goal with
  | FR : rw_cells _ _ (bv_unsigned ?sp + -48) _, ST' : stk _ _ ?lo _ |- _ => release_frame FR ST' (bv_unsigned sp)
  end.

